import{_ as l,a0 as d,w as o,s as g,ao as p,I as n,x as s,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 RHEL 9 上分步安裝 PgAdmin4 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 9 上分步安裝 PgAdmin4 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 9 上分步安裝 PgAdmin4 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 9 上分步安裝 PgAdmin4 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step","title":"如何在 RHEL 9 上分步安裝 PgAdmin4","tag":"202303","desc":""},"relativePath":"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step.md","filePath":"[post].md"}'),r={name:"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step.md"};function h(m,i,c,u,b,k){const t=d("Link");return o(),g("div",null,[i[18]||(i[18]=p('<h1 id="如何在-rhel-9-上分步安裝-pgadmin4" tabindex="-1">如何在 RHEL 9 上分步安裝 PgAdmin4 <a class="header-anchor" href="#如何在-rhel-9-上分步安裝-pgadmin4" aria-label="Permalink to “如何在 RHEL 9 上分步安裝 PgAdmin4”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/12/080937o03a11xsz99zawzm.jpg" alt=""></p><p>PgAdmin4 是一個自由開源的基於網絡的 PostgreSQL 管理和開發平台。它可以與本地或遠程的服務器上的 PostgreSQL 資料庫服務器進行交互，並使用直觀的交互式儀表板顯示服務器的統計數據。</p><p>PgAdmin4 是對 PgAdmin3 的重寫，提供了以下顯著的功能：</p><ul><li>具有直觀的實時監控儀表盤的響應式 Web UI。</li><li>改進的 Web 界面，具有很酷的新面板和圖標。</li><li>帶有語法高亮的 SQL 查詢編輯器。</li><li>全面的文檔。</li><li>幫助你入門的有用提示。</li></ul><p>在本指南中，我們將演示如何在 RHEL 9 上安裝 PgAdmin4。</p><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3>',7)),n("p",null,[i[1]||(i[1]=s("在開始之前，確保你有一台 RHEL 9 服務器實例並安裝了 PostgreSQL 資料庫。請查看如何在 RHEL 9 上 ",-1)),e(t,{href:"https://www.linuxtechi.com/how-to-install-postgresql-on-rhel/"},{default:a(()=>[...i[0]||(i[0]=[s("安裝 PostgreSQL 15",-1)])]),_:1}),i[2]||(i[2]=s(" 的指南。",-1))]),i[19]||(i[19]=p('<p>在安裝了 PostgreSQL 服務器後，繼續執行以下步驟。</p><h3 id="步驟-1-在-rhel-9-上添加-pgadmin4-倉庫" tabindex="-1">步驟 1）在 RHEL 9 上添加 PgAdmin4 倉庫 <a class="header-anchor" href="#步驟-1-在-rhel-9-上添加-pgadmin4-倉庫" aria-label="Permalink to “步驟 1）在 RHEL 9 上添加 PgAdmin4 倉庫”">​</a></h3><p>第一步是在 RHEL 9 上添加 PgAdmin4 倉庫。但首先要安裝 EPEL 倉庫，它提供了基本的軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install https://dl.fedoraproject.org/pub/epel/epel-release-latest-9.noarch.rpm</span></span></code></pre></div><p>接下來，安裝 PgAdmin4 倉庫，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y https://ftp.postgresql.org/pub/pgadmin/pgadmin4/yum/pgadmin4-redhat-repo-2-1.noarch.rpm</span></span></code></pre></div><p>完成後，為 PgAdmin4 和 EPEL 倉庫建立一個緩存，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf makecache</span></span></code></pre></div><h3 id="步驟-2-在-rhel-9-上安裝-pgadmin4" tabindex="-1">步驟 2）在 RHEL 9 上安裝 PgAdmin4 <a class="header-anchor" href="#步驟-2-在-rhel-9-上安裝-pgadmin4" aria-label="Permalink to “步驟 2）在 RHEL 9 上安裝 PgAdmin4”">​</a></h3><p>安裝好 PgAdmin4 和 EPEL 倉庫後，繼續使用 DNF 包管理器安裝 PgAdmin4，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install pgadmin4 -y</span></span></code></pre></div><p>這將安裝許多軟件包，包括 PgAdmin4、Apache HTTP web 服務器和 Python 軟件包，僅舉幾例：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Install-pgadmin4-rhel9-dnf-command.png" alt=""></p><p>要確認 PgAdmin4 是否已經安裝，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm -qi pgadmin4</span></span></code></pre></div><p>這將打印出相當多的信息，包括已安裝軟件包的名稱、版本、發行和架構。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Pgadmin4-RPM-Package-Information-RHEL9.png" alt=""></p><h3 id="步驟-3-在-rhel-9-上啓動-啓用-pgadmin4" tabindex="-1">步驟 3）在 RHEL 9 上啓動/啓用 PgAdmin4 <a class="header-anchor" href="#步驟-3-在-rhel-9-上啓動-啓用-pgadmin4" aria-label="Permalink to “步驟 3）在 RHEL 9 上啓動/啓用 PgAdmin4”">​</a></h3><p>此時，PgAdmin4 已成功安裝。然而，你需要更進一步，讓它運行起來。要啓動 PgAdmin4 服務，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start httpd</span></span></code></pre></div><p>還要確保每次系統啓動時都能啓動該服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable httpd</span></span></code></pre></div><p>要確認 PgAdmin4 正在運行，請執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status httpd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Start-Enable-Http-Pgadmin-RHEL9.png" alt=""></p><h3 id="步驟-4-在-rhel-9-上初始化-pgadmin4" tabindex="-1">步驟 4）在 RHEL 9 上初始化 PgAdmin4 <a class="header-anchor" href="#步驟-4-在-rhel-9-上初始化-pgadmin4" aria-label="Permalink to “步驟 4）在 RHEL 9 上初始化 PgAdmin4”">​</a></h3><p>PgAdmin4 軟件包提供了一個可配置的腳本來設置 PgAdmin 網絡服務。這允許你創建一個用户賬户，用來驗證和配置 SELinux 策略和 Apache Web 服務器。</p><p>因此，如下運行該腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/pgadmin4/bin/setup-web.sh</span></span></code></pre></div><p>提供你將在登錄頁面上作為登錄憑證使用的電子郵件和密碼。</p><p>注意:有時，你可能會遇到如下 “semanage: command not found” 的錯誤。這表明缺少 <code>semanage</code> 包。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/semange-not-found-pgadmin4-rhel9.png" alt=""></p><p>Semanage 是 SELinux（安全增強型 Linux）策略管理工具的簡稱，是一個用於配置 SELinux 策略某些方面的工具，不需要對策略源進行修改或重新編譯。</p><p>為了解決這個錯誤，你需要檢查提供 <code>semanage</code> 的軟件包。你可以通過運行以下命令來完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf provides /usr/sbin/semanage</span></span></code></pre></div><p>從輸出中，你可以看到 <code>semanage</code> 是由 <code>policycoreutils-python-utils-3.3-6.el9_0.noarch</code> 包提供的。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/DNF-Whatprovides-semanage-RHEL9.png" alt=""></p><p>要安裝這個軟件包，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install policycoreutils-python-utils -y</span></span></code></pre></div><p>再一次如下運行 Pgadmin4 安裝腳本。 提供電子郵件地址和密碼，在提示時輸入 <code>y</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/pgadmin4/bin/setup-web.sh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/pgadmin-setup-web-script-rhel9.png" alt=""></p><h3 id="步驟-5-訪問-pgadmin4-的-web-界面" tabindex="-1">步驟 5）訪問 PgAdmin4 的 Web 界面 <a class="header-anchor" href="#步驟-5-訪問-pgadmin4-的-web-界面" aria-label="Permalink to “步驟 5）訪問 PgAdmin4 的 Web 界面”">​</a></h3><p>此時，PgAdmin4 已經成功安裝。要從網絡瀏覽器訪問它，請前往以下地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://server-ip/pgadmin4</span></span></code></pre></div><p>你會看到登錄網頁界面。請確保提供你在運行安裝腳本時提供的 Email 和密碼，並點擊 “<ruby>登錄<rt>Login</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Pgadmin4-Login-Page-RHEL9.png" alt=""></p><p>登錄後，PgAdmin4 的儀表板將出現在視圖中，如圖所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Dashboard-Pgadmin4-RHEL9.png" alt=""></p><p>要添加一個可以由 PgAdmin4 管理的服務器，請點擊 “<ruby>添加新服務器<rt>Add New Server</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Add-New-PostgreSQL-to-Pgadmin4-RHEL9.png" alt=""></p><p>在 “<ruby>通用<rt>General</rt></ruby>” 選項卡中，填寫服務器的名稱，並添加註釋，以便更好地描述：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/General-Description-Pgadmin-New-PostgreSQL.png" alt=""></p><p>接下來，點擊 “<ruby>連接<rt>Connection</rt></ruby>”，填寫主機名/地址、端口、維護資料庫、用户名和密碼。然後最後點擊 “<ruby>保存<rt>Save</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Connection-Details-PostgreSQL-Pgadmin4-GUI.png" alt=""></p><p>此後，你會看到 PosrgreSQL 服務器的統計數據顯示在互動和直觀的儀表板上。在左邊的側邊欄，你可以瀏覽各種 PostgreSQL 參數：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/PostgreSQL-Statistics-Dashboard-Pgadmin4.png" alt=""></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我們希望你覺得本指南內容豐富，請在下面的評論部分發表你的疑問和反饋。</p><hr>',60)),n("p",null,[i[4]||(i[4]=s("via: ",-1)),e(t,{href:"https://www.linuxtechi.com/how-to-install-pgadmin-on-rhel/"},{default:a(()=>[...i[3]||(i[3]=[s("https://www.linuxtechi.com/how-to-install-pgadmin-on-rhel/",-1)])]),_:1})]),n("p",null,[i[9]||(i[9]=s("作者：",-1)),e(t,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...i[5]||(i[5]=[s("Pradeep Kumar",-1)])]),_:1}),i[10]||(i[10]=s(" 選題：",-1)),e(t,{href:"https://github.com/lkxed/"},{default:a(()=>[...i[6]||(i[6]=[s("lkxed",-1)])]),_:1}),i[11]||(i[11]=s(" 譯者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:a(()=>[...i[7]||(i[7]=[s("geekpi",-1)])]),_:1}),i[12]||(i[12]=s(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[8]||(i[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[13]||(i[13]=[s("LCTT",-1)])]),_:1}),i[16]||(i[16]=s(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...i[14]||(i[14]=[s("Linux中國",-1)])]),_:1}),i[17]||(i[17]=s(" 榮譽推出",-1))])])}const y=l(r,[["render",h]]);export{w as __pageData,y as default};
